content.css:
.skpi-root {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
}
.skpi-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  flex: 1 1 auto;
}
.skpi-value-ref-row {
  display: flex;
  min-width: 0;
}
.skpi-kpi-var {
  display: flex;
  min-width: 0;
}
.skpi-layout-sep {
  flex: 0 0 auto;
  width: 1px;
  min-height: 1em;
  align-self: stretch;
}
.skpi-main-row {
  display: flex;
  align-items: baseline;
  justify-content: inherit;
}
.skpi-value-block {
  white-space: nowrap;
}
.skpi-value {
  line-height: 1.05;
}
.skpi-label {
  min-width: 0;
}
.skpi-indicator {
  user-select: none;
}
.skpi-variance {
  line-height: 1.2;
}
.skpi-refs-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 1.1em;
  row-gap: 0.15em;
  min-width: 0;
  max-width: 100%;
}
.skpi-change {
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
}
.skpi-pct {
  line-height: 1.2;
}
.skpi-variance-label {
  line-height: 1.2;
  white-space: nowrap;
}
.skpi-previous,
.skpi-target {
  line-height: 1.2;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.skpi-spark {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.skpi-timeline {
  display: flex;
  flex: 0 0 auto;
  width: 100%;
  overflow: hidden;
  margin-top: 2px;
  line-height: 1.1;
}
.skpi-timeline-label {
  flex: 0 1 auto;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.skpi-timeline-label:first-child {
  text-align: left;
}
.skpi-timeline-label:last-child {
  text-align: right;
}
.skpi-spark-svg {
  display: block;
  width: 100%;
  height: 100%;
}
.skpi-spark-line,
.skpi-spark-line-hl,
.skpi-spark-area,
.skpi-spark-points,
.skpi-hover-dot {
  pointer-events: none;
}
.skpi-spark-hover rect {
  pointer-events: all;
}
.cbt-landing {
  align-items: center;
  justify-content: center;
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
  background: #fafbfc;
  position: absolute;
  top: 0;
  left: 0;
  z-index: 50;
  width: 100%;
  height: 100%;
}
.cbt-landing-inner {
  text-align: center;
  max-width: 480px;
  padding: 24px;
}
.cbt-landing-logo {
  margin-bottom: 16px;
}
.cbt-landing-title {
  font-size: 20px;
  font-weight: 600;
  color: #1a1a1a;
  margin-bottom: 4px;
  letter-spacing: -0.3px;
}
.cbt-landing-company {
  font-size: 12px;
  color: #888;
  margin-bottom: 16px;
}
.cbt-landing-divider {
  width: 60px;
  height: 2px;
  margin: 0 auto 20px;
  border-radius: 1px;
}
.cbt-landing-instructions {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 20px;
  text-align: left;
}
.cbt-landing-step {
  display: flex;
  align-items: center;
  gap: 12px;
}
.cbt-landing-step-num {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  color: #fff;
  font-size: 13px;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.cbt-landing-step-text {
  font-size: 13px;
  color: #444;
  line-height: 1.4;
}
.cbt-landing-step-text strong {
  color: #1a1a1a;
  font-weight: 600;
}
.cbt-landing-features {
  font-size: 11px;
  color: #999;
  line-height: 1.7;
  margin-bottom: 16px;
}
.cbt-landing-contact {
  font-size: 11px;
}
.cbt-landing-contact a {
  text-decoration: none;
}
.cbt-landing-contact a:hover {
  text-decoration: underline;
}
